import type { Article, ArticleSection, Chapter, GlossaryTerm, RichText } from '../types';

const subjectId = 'recht';
const updatedAt = Date.UTC(2026, 10, 18);
const bgb = 'https://www.gesetze-im-internet.de/bgb/';

type Topic = {
  id: string;
  parentId?: string;
  number: string;
  title: string;
  intro: string;
  sections: ArticleSection[];
};

function richText(text: string): RichText[] {
  const parts: RichText[] = [];
  let offset = 0;
  for (const hit of text.matchAll(/\[\[([ta]):([a-z0-9-]+)\|([^\]]+)\]\]/g)) {
    const [match, kind, id, label] = hit;
    if (hit.index > offset) parts.push({ text: text.slice(offset, hit.index) });
    parts.push(kind === 't' ? { text: label, termId: id } : { text: label, articleId: id });
    offset = hit.index + match.length;
  }
  if (offset < text.length) parts.push({ text: text.slice(offset) });
  return parts;
}

const section = (id: string, title: string, ...paragraphs: string[]): ArticleSection => ({
  id,
  title,
  paragraphs: paragraphs.map(richText),
});

const check = (question: string, answer: string): ArticleSection => ({
  ...section('transferfrage', 'Selbstkontrolle', question),
  hint: { label: 'SELBSTKONTROLLE', title: 'Musterantwort', content: answer },
});

